#include "RuntimeWorld.h"
#include <cstdio>
int main(){unsigned rejected=0;for(unsigned mode=0;mode<3;++mode){Scene s;auto& o=s.CreateObject("ordinary environment owner");if(mode==0){o.body=SceneBodyComponent{};o.celestial=SceneCelestialComponent{};o.celestial->gravitationalParameter=62784;o.atmosphere=SceneAtmosphereComponent{};}else if(mode==1){o.body=SceneBodyComponent{};o.body->motion=SceneBodyMotion::Dynamic;o.combustible=SceneCombustibleComponent{};}else{o.liquidBasin=LiquidBasinSettings{};}RuntimeWorld w;w.legacyGameplay=false;std::string e;if(!w.Build(s,nullptr,e)){std::printf("BUILD FAIL %s\n",e.c_str());return 2;}bool accepted=w.RequestOrigin({512,0,0},e);std::printf("%s origin accepted=%d error=%s\n",mode==0?"atmosphere":mode==1?"combustion":"conserved liquid",accepted,e.c_str());rejected+=!accepted;}return rejected?1:0;}
